INSERT INTO repo_esd_objectives (esd_objective_id, domain, objective_no, text, status) VALUES ('ESD_SDG14_SOC_01', 'Socio-emotional', '1', 'The learner is able to argue for sustainable fishing practices.', 'Active'), ('ESD_SDG14_SOC_02', 'Socio-emotional', '2', 'The learner is able to show people the impact humanity is having on the oceans (biomass loss, acidification, pollution, etc.) and the value of clean healthy oceans.', 'Active'), ('ESD_SDG14_SOC_03', 'Socio-emotional', '3', 'The learner is able to influence groups that engage in unsustainable production and consumption of ocean products.', 'Active'), ('ESD_SDG14_SOC_04', 'Socio-emotional', '4', 'The learner is able to reflect on their own dietary needs and question whether their dietary habits make sustainable use of limited resources of seafood.', 'Active'), ('ESD_SDG14_SOC_05', 'Socio-emotional', '5', 'The learner is able to empathize with people whose livelihoods are affected by changing fishing practices.', 'Active'), ('ESD_SDG14_BEH_01', 'Behavioural', '1', 'The learner is able to research their country’s dependence on the sea.', 'Active'), ('ESD_SDG14_BEH_02', 'Behavioural', '2', 'The learner is able to debate sustainable methods such as strict fishing quotas and moratoriums on species in danger of extinction.', 'Active'), ('ESD_SDG14_BEH_03', 'Behavioural', '3', 'The learner is able to identify, access and buy sustainably harvested marine life, e.g. ecolabel certified products.', 'Active'), ('ESD_SDG14_BEH_04', 'Behavioural', '4', 'The learner is able to contact their representatives to discuss overfishing as a threat to local livelihoods.', 'Active'), ('ESD_SDG14_BEH_05', 'Behavioural', '5', 'The learner is able to campaign for expanding no-fish zones and marine reserves and for their protection on a scientific basis.', 'Active'), ('ESD_SDG15_COG_01', 'Cognitive', '1', 'The learner understands basic ecology with reference to local and global ecosystems, identifying local species and understanding the measure of biodiversity.', 'Active'), ('ESD_SDG15_COG_02', 'Cognitive', '2', 'The learner understands the manifold threats posed to biodiversity, including habitat loss, deforestation, fragmentation, overexploitation and invasive species, and can relate these threats to their local biodiversity.', 'Active'), ('ESD_SDG15_COG_03', 'Cognitive', '3', 'The learner is able to classify the ecosystem services of the local ecosystems including supporting, provisioning, regulating and cultural services and ecosystems services for disaster risk reduction.', 'Active'), ('ESD_SDG15_COG_04', 'Cognitive', '4', 'The learner understands the slow regeneration of soil and the multiple threats that are destroying and removing it much faster than it can replenish itself, such as poor farming or forestry practice.', 'Active'), ('ESD_SDG15_COG_05', 'Cognitive', '5', 'The learner understands that realistic conservation strategies work outside pure nature reserves to also improve legislation, restore degraded habitats and soils, connect wildlife corridors, sustainable agriculture and forestry, and redress humanity’s relationship to wildlife.', 'Active'), ('ESD_SDG15_SOC_01', 'Socio-emotional', '1', 'The learner is able to argue against destructive environmental practices that cause biodiversity loss.', 'Active'), ('ESD_SDG15_SOC_02', 'Socio-emotional', '2', 'The learner is able to argue for the conservation of biodiversity on multiple grounds including ecosystems services and intrinsic value.', 'Active'), ('ESD_SDG15_SOC_03', 'Socio-emotional', '3', 'The learner is able to connect with their local natural areas and feel empathy with non-human life on Earth.', 'Active'), ('ESD_SDG15_SOC_04', 'Socio-emotional', '4', 'The learner is able to question the dualism of human/nature and realizes that we are a part of nature and not apart from nature.', 'Active'), ('ESD_SDG15_SOC_05', 'Socio-emotional', '5', 'The learner is able to create a vision of a life in harmony with nature.', 'Active'), ('ESD_SDG15_BEH_01', 'Behavioural', '1', 'The learner is able to connect with local groups working toward biodiversity conservation in their area.', 'Active'), ('ESD_SDG15_BEH_02', 'Behavioural', '2', 'The learner is able to effectively use their voice effectively in decision-making processes to help urban and rural areas become more permeable to wildlife through the establishment of wildlife corridors, agro-environmental schemes, restoration ecology and more.', 'Active'), ('ESD_SDG15_BEH_03', 'Behavioural', '3', 'The learner is able to work with policy-makers to improve legislation for biodiversity and nature conservation, and its implementation.', 'Active'), ('ESD_SDG15_BEH_04', 'Behavioural', '4', 'The learner is able to highlight the importance of soil as our growing material for all food and the importance of remediating or stopping the erosion of our soils.', 'Active'), ('ESD_SDG15_BEH_05', 'Behavioural', '5', 'The learner is able to campaign for international awareness of species exploitation and work for the implementation and development of CITES (Convention on International Trade in Endangered Species of Wild Fauna and Flora) regulations.', 'Active'), ('ESD_SDG16_COG_01', 'Cognitive', '1', 'The learner understands concepts of justice, inclusion and peace and their relationship to law.', 'Active'), ('ESD_SDG16_COG_02', 'Cognitive', '2', 'The learner understands their local and national legislative and governance systems, how they represent them and that they can be abused through corruption.', 'Active'), ('ESD_SDG16_COG_03', 'Cognitive', '3', 'The learner is able to compare their system of justice with those of other countries.', 'Active'), ('ESD_SDG16_COG_04', 'Cognitive', '4', 'The learner understands the importance of individuals and groups in upholding justice, inclusion and peace and supporting strong institutions in their country and globally.', 'Active'), ('ESD_SDG16_COG_05', 'Cognitive', '5', 'The learner understands the importance of the international human rights framework.', 'Active'), ('ESD_SDG16_SOC_01', 'Socio-emotional', '1', 'The learner is able to connect with others who can help them in facilitating peace, justice, inclusion and strong institutions in their country.', 'Active'), ('ESD_SDG16_SOC_02', 'Socio-emotional', '2', 'The learner is able to debate local and global issues of peace, justice, inclusion and strong institutions.', 'Active'), ('ESD_SDG16_SOC_03', 'Socio-emotional', '3', 'The learner is able to show empathy with and solidarity for those suffering from injustice in their own country as well as in other countries.', 'Active'), ('ESD_SDG16_SOC_04', 'Socio-emotional', '4', 'The learner is able to reflect on their role in issues of peace, justice, inclusion and strong institutions.', 'Active'), ('ESD_SDG16_SOC_05', 'Socio-emotional', '5', 'The learner is able to reflect on their own personal belonging to diverse groups (gender, social, economic, political, ethnical, national, ability, sexual orientation etc.) their access to justice and their shared sense of humanity.', 'Active'), ('ESD_SDG16_BEH_01', 'Behavioural', '1', 'The learner is able to critically assess issues of peace, justice, inclusion and strong institutions in their region, nationally and globally.', 'Active'), ('ESD_SDG16_BEH_02', 'Behavioural', '2', 'The learner is able to publicly demand and support the development of policies promoting peace, justice, inclusion and strong institutions.', 'Active'), ('ESD_SDG16_BEH_03', 'Behavioural', '3', 'The learner is able to collaborate with groups that are currently experiencing injustice and/or conflicts.', 'Active'), ('ESD_SDG16_BEH_04', 'Behavioural', '4', 'The learner is able to become an agent of change in local decision-making, speaking up against injustice.', 'Active'), ('ESD_SDG16_BEH_05', 'Behavioural', '5', 'The learner is able to contribute to conflict resolution at the local and national level.', 'Active'), ('ESD_SDG17_COG_01', 'Cognitive', '1', 'The learner understands global issues, including issues of financing for development, taxation, debt and trade policies, and the interconnectedness and interdependency of different countries and populations.', 'Active'), ('ESD_SDG17_COG_02', 'Cognitive', '2', 'The learner understands the importance of global multi-stakeholder partnerships and the shared accountability for sustainable development and knows examples of networks, institutions, campaigns of global partnerships.', 'Active'), ('ESD_SDG17_COG_03', 'Cognitive', '3', 'The learner knows the concepts of global governance and global citizenship.', 'Active'), ('ESD_SDG17_COG_04', 'Cognitive', '4', 'The learner recognizes the importance of cooperation on and access to science, technology and innovation, and knowledge sharing.', 'Active'), ('ESD_SDG17_COG_05', 'Cognitive', '5', 'The learner knows concepts for measuring progress on sustainable development.', 'Active'), ('ESD_SDG17_SOC_01', 'Socio-emotional', '1', 'The learner is able to raise awareness about the importance of global partnerships for sustainable development.', 'Active'), ('ESD_SDG17_SOC_02', 'Socio-emotional', '2', 'The learner is able to work with others to promote global partnerships for sustainable development and demand governments’ accountability for the SDGs.', 'Active'), ('ESD_SDG17_SOC_03', 'Socio-emotional', '3', 'The learner is able to take ownership of the SDGs.', 'Active'), ('ESD_SDG17_SOC_04', 'Socio-emotional', '4', 'The learner is able to create a vision for a sustainable global society.', 'Active'), ('ESD_SDG17_SOC_05', 'Socio-emotional', '5', 'The learner is able to experience a sense of belonging to a common humanity, sharing values and responsibilities, based on human rights.', 'Active') ON CONFLICT DO NOTHING;